Assign(targets=[Name(id='SCRIPT', ctx=Store())], value=Constant(value='
(function(){
  var svg = document.getElementById('schematic');
  if(!svg || !svg.systemap || !svg.page){ return; }
  var A = svg.systemap, P = svg.page, W = window.systemapWorkspace || {};
  var STEPS = W.guide || [], KEY = 'systemap-guide';
  function byId(id){ return document.getElementById(id); }
  function esc(s){ return String(s).replace(/[&<>"]/g, function(c){
    return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]; }); }
  var LAY = {};
  A.layers.forEach(function(l){ LAY[l.id] = l; });
  var card = byId('guide'), read = byId('inspector-empty'), g = 0;

  // ---- the guide card -------------------------------------------------------
  function seen(){ try { return localStorage.getItem(KEY) === 'done'; } catch(e){ return true; } }
  function done(){ try { localStorage.setItem(KEY, 'done'); } catch(e){} }
  function apply(step){
    if(step.journey !== undefined){
      hideCard(); P.setMode('trace'); P.journey.start(step.journey); return;
    }
    if(P.mode() !== 'understand'){ P.setMode('understand'); }
    P.setLayer(step.layer);
  }
  function renderCard(){
    if(!card || !STEPS.length){ return; }
    var step = STEPS[g], nxt = STEPS[g + 1];
    byId('guide-count').textContent = (g + 1) + ' of ' + STEPS.length;
    byId('guide-bar').innerHTML = STEPS.map(function(_s, k){
      return '<span class="' + (k <= g ? 'on' : '') + '"></span>'; }).join('');
    byId('guide-title').textContent = step.title;
    byId('guide-text').textContent = step.text;
    byId('guide-next').textContent = nxt ? 'Next: ' + nxt.title
      : (step.journey !== undefined ? 'Start the sequence' : 'Close');
  }
  // ---- the map moves clear of the card (board 10) ---------------------------
  // The zoom stays. The map moves left until the card does not cover it, but
  // not past the left edge of the map frame. When the card closes, the map
  // goes back to Fit if the reader did not move it.
  var moved = null;
  function clearOfCard(){
    var view = svg.querySelector('.view');
    if(!card || card.hidden || !view || !A.view.isFit()){ return; }
    var m = view.getBoundingClientRect(), c = card.getBoundingClientRect();
    var frame = svg.getBoundingClientRect();
    if(m.bottom <= c.top || m.top >= c.bottom){ return; }
    var dx = Math.min(m.right - (c.left - 32), m.left - (frame.left + 24));
    var v = A.view.snapshot(), base = A.view.zoom() / v.k;
    if(!(dx > 0) || !(base > 0)){ return; }
    moved = {k:v.k, tx:v.tx - dx / base, ty:v.ty};
    A.view.restore(moved, true);
  }
  function hideCard(){
    if(card && !card.hidden){
      card.hidden = true;
      var v = A.view.snapshot();
      if(moved && Math.abs(v.tx - moved.tx) < 0.5 && Math.abs(v.ty - moved.ty) < 0.5
        && Math.abs(v.k - moved.k) < 1e-3){ A.view.fit(); }
      moved = null;
    }
    done();
  }
  function goTo(k){ g = k; renderCard(); apply(STEPS[g]); render(); }
  if(card){
    byId('guide-next').addEventListener('click', function(){
      if(g + 1 < STEPS.length){ goTo(g + 1); }
      else if(STEPS[g].journey !== undefined){ apply(STEPS[g]); }
      else { hideCard(); }
    });
    byId('guide-close').addEventListener('click', hideCard);
    card.addEventListener('keydown', function(e){
      if(e.key === 'Escape'){ hideCard(); e.stopPropagation(); }
    });
  }
  svg.addEventListener('systemap:mode', function(e){
    if(card && e.detail.mode !== 'understand'){ card.hidden = true; }
  });

  // ---- the Details panel -----------------------------------------------------
  // The section for the layer comes first: page_mapview and page_groups give
  // it through P.readers. The guide steps follow it as a short list.
  function section(L){
    var readers = P.readers || [];
    for(var k = 0; k < readers.length; k++){
      var out = readers[k](L);
      if(out){ return out; }
    }
    return {html:'<section class="read__section"><p class="read__q">'
      + esc(LAY[L] ? LAY[L].question : '') + '</p></section>'};
  }
  function guideHtml(L){
    var at = -1;
    STEPS.forEach(function(s, k){ if(s.layer === L && at < 0){ at = k; } });
    return '<section class="read__guide" aria-label="Guide"><div class="seq-row">'
      + '<h3 class="seq-kicker">READ THE MAP</h3><span class="seq-count">'
      + (at >= 0 ? (at + 1) + ' of ' : '') + STEPS.length + '</span></div>'
      + '<ol class="read__steps">' + STEPS.map(function(s, k){
        return '<li><button type="button" class="read__step" data-guide="' + k
          + '" aria-current="' + (k === at) + '"><b>' + (k + 1) + '</b><span>' + esc(s.title)
          + '</span><small>' + esc(s.layer ? (LAY[s.layer] ? LAY[s.layer].label : s.layer)
          : 'Sequence') + '</small></button></li>';
      }).join('') + '</ol></section>';
  }
  function render(){
    if(!read || read.hidden){ return; }
    var L = A.state.layer, sec = section(L);
    read.innerHTML = '<div class="read">' + sec.html + (STEPS.length ? guideHtml(L) : '')
      + '</div>';
    Array.prototype.slice.call(read.querySelectorAll('[data-guide]')).forEach(function(b){
      b.addEventListener('click', function(){ g = +b.dataset.guide; renderCard();
        apply(STEPS[g]); });
    });
    if(sec.bind){ sec.bind(read); }
  }
  ['systemap:layer', 'systemap:panel', 'systemap:mode', 'systemap:clear'].forEach(function(name){
    svg.addEventListener(name, render);
  });
  P.renderRead = render;
  if(card && STEPS.length && !seen() && P.mode() === 'understand'){
    // The map moves after the Map view opens the panel: the frame then has its width.
    card.hidden = false; renderCard(); P.afterBoot = clearOfCard;
  }
  render();
})();
'))

Assign(targets=[Name(id='SCRIPT', ctx=Store())], value=Constant(value="
(function(){
  if(window.parent !== window || !window.EventSource){ return; }
  var svg = document.getElementById('schematic');
  var A = svg && svg.systemap, P = svg && svg.page;
  var C = document.getElementById('changemap'), M = C && C.systemap;
  var MODES = ['understand', 'trace', 'change'];
  function edgeKey(map, i){
    var e = map.edges[i];
    return e ? {from:e.from, to:e.to, art:e.art, id:e.id} : null;
  }
  function edgeAt(map, key){
    if(!key){ return -1; }
    for(var i = 0; i < map.edges.length; i++){
      var e = map.edges[i];
      if(e.from === key.from && e.to === key.to && e.art === key.art
        && (!key.id || e.id === key.id)){ return i; }
    }
    return -1;
  }
  function has(table, key){ return Object.prototype.hasOwnProperty.call(table, key); }
  function camera(map){ return map.view.isFit() ? null : map.view.snapshot(); }
  function journeyAt(id){
    for(var k = 0; k < A.journeys.length; k++){ if(A.journeys[k].id === id){ return k; } }
    return -1;
  }
  function viewOf(){
    var at = P.journey.state(), j = A.journeys[at.j];
    return {path:location.pathname, mode:P.mode(), layer:A.state.layer, focus:A.state.focus,
      edge:edgeKey(A, A.state.edge), camera:camera(A),
      journey:j ? {id:j.id, s:at.s, view:at.view} : null,
      change:M ? {focus:M.state.focus, edge:edgeKey(M, M.state.edge), camera:camera(M)} : null};
  }
  function save(){
    if(!A || !P){ return; }
    try { sessionStorage.setItem(KEY, JSON.stringify(viewOf())); } catch(e){}
  }
  function saved(){
    var raw = null;
    try { raw = sessionStorage.getItem(KEY); sessionStorage.removeItem(KEY); }
    catch(e){ return null; }
    try { return JSON.parse(raw); } catch(e){ return null; }
  }
  function putMode(v){
    var k = v.journey ? journeyAt(v.journey.id) : -1;
    if(v.mode === 'trace' && k >= 0){
      P.journey.route(k);
      if(v.journey.view === 'steps'){ P.sequence.go('steps', v.journey.s, 'keep'); }
    } else if(MODES.indexOf(v.mode) >= 0 && v.mode !== P.mode()){ P.setMode(v.mode); }
  }
  function putFocus(map, focus, edge){
    // A saved flow that the new page does not have gives no selection, not its component.
    var i = edgeAt(map, edge);
    var known = !!focus && focus !== '_meta' && has(map.detail, focus);
    if(known && (!edge || i >= 0)){ map.select(focus, i); }
    else if(map.state.focus){ map.clear(); }
  }
  function putCamera(map, view){
    if(view){ map.view.restore(view, true); } else if(!map.view.isFit()){ map.view.fit(true); }
  }
  function restore(){
    var v = saved();
    if(!v || v.path !== location.pathname || !A || !P){ return; }
    // A saved sequence that the new page does not have gives the Map view with no selection.
    // The Sequences view always shows a sequence, so it cannot open without a selection.
    var gone = v.mode === 'trace' && !!v.journey && journeyAt(v.journey.id) < 0;
    P.restoring(true);
    try {
      if(v.layer === 'all' || has(A.detail._meta.readings, v.layer)){ P.setLayer(v.layer); }
      if(!gone){ putMode(v); }
      putFocus(A, gone ? '' : v.focus, gone ? null : v.edge);
      if(M && v.change){ putFocus(M, v.change.focus, v.change.edge); }
    } finally { P.restoring(false); }
    // The page frames a selection in the next frame. The camera comes after that framing.
    window.requestAnimationFrame(function(){
      P.restoring(true);
      try {
        putCamera(A, v.camera);
        if(M && v.change){ putCamera(M, v.change.camera); }
      } finally { P.restoring(false); }
    });
  }
  function notice(text){
    var n = document.getElementById(NOTICE);
    if(!n){
      n = document.createElement('div');
      n.id = NOTICE;
      n.setAttribute('role', 'status');
      n.setAttribute('style', 'position:fixed;left:16px;bottom:16px;z-index:60;'
        + 'max-width:min(560px,calc(100vw - 32px));padding:8px 12px;border-radius:6px;'
        + 'border:1px solid var(--line-2,#888);background:var(--raised,#fff);'
        + 'color:var(--ink,#111);font:13px/1.4 var(--fs,sans-serif)');
      document.body.appendChild(n);
    }
    n.textContent = 'The map is not updated: ' + String(text).split('\n')[0];
  }
  restore();
  var source = new EventSource('/events');
  source.addEventListener('rendered', function(e){
    var d = {};
    try { d = JSON.parse(e.data); } catch(_x){}
    if(d.version > VERSION){ save(); source.close(); location.reload(); }
  });
  // A version that the command cannot render gives a server event with the name error.
  // A broken connection gives an error event without data: the command stopped, so the
  // script stops too.
  source.addEventListener('error', function(e){
    if(typeof e.data !== 'string'){ source.close(); return; }
    var d = {};
    try { d = JSON.parse(e.data); } catch(_x){}
    if(d.text){ notice(d.text); }
  });
})();
"))

